export type ListAuthConfig = {
    data: Array<{
        client_id: string;
        created_at: string;
        /**
         * Whether the app has secret settings (which are never answered).
         */
        has_secret_settings: boolean;
        /**
         * `ac_…`.
         */
        id: string;
        provider: string;
        scopes: Array<string>;
        /**
         * The provider's own settings for the app; an empty object when it has none.
         */
        settings: {
            [key: string]: unknown;
        };
        updated_at: string;
    }>;
    /**
     * Pass as `after` for the next batch; null on the last.
     */
    next_cursor?: string | null;
    /**
     * Pass as `before` for the previous batch; null on the first.
     */
    previous_cursor?: string | null;
};

export type ListConnectedAccount = {
    data: Array<{
        access_token_expires_at?: string | null;
        alias?: string | null;
        auth_config_id: string;
        created_at: string;
        /**
         * What the connection acts as: `oauth` (the user who consented) or `app_installation` (an
         * installation of the auth config's app, its tokens minted when an action runs). An open
         * string.
         */
        credential_kind: string;
        id: string;
        /**
         * The installation an `app_installation` connection acts as.
         */
        installation_id?: string | null;
        /**
         * Why the last refresh or the consent failed.
         */
        last_error?: string | null;
        provider: string;
        /**
         * The pending refresh task's name, and when it runs.
         */
        refresh_task?: string | null;
        refresh_task_at?: string | null;
        /**
         * The scopes the provider granted.
         */
        scope?: string | null;
        /**
         * Whether setup is complete: osiris holds the tokens and, when they can be refreshed, their
         * refresh is scheduled. When false, the connection can't be used.
         */
        setup_complete: boolean;
        /**
         * `pending` (the consent is open), `active`, `disabled` (no refresh is scheduled, so the
         * connection can't be used: after a failed connect the user must connect again; after a
         * refresh, osiris schedules it again by itself), `expired` (the provider refused a refresh
         * or the grant is gone: reconnect) or `failed` (the consent failed or was never finished). A
         * connection is only reported `active` when its setup is complete.
         */
        status: string;
        updated_at: string;
        user_id: string;
    }>;
    /**
     * Pass as `after` for the next batch; null on the last.
     */
    next_cursor?: string | null;
    /**
     * Pass as `before` for the previous batch; null on the first.
     */
    previous_cursor?: string | null;
};

export type ListTrigger = {
    data: Array<{
        config: {
            [key: string]: unknown;
        };
        connected_account_id: string;
        created_at: string;
        /**
         * `tr_…`.
         */
        id: string;
        /**
         * Why it failed.
         */
        last_error?: string | null;
        /**
         * When it next checks the provider, for a kind that checks on a schedule.
         */
        next_check_at?: string | null;
        provider: string;
        /**
         * `active` (its deliveries are published) or `failed` (the provider refused it; create it
         * again). An open string.
         */
        status: string;
        /**
         * The provider's id of what osiris created there, such as a webhook's id.
         */
        subscription_id?: string | null;
        /**
         * Its kind, `<provider>.<kind>`.
         */
        trigger: string;
        updated_at: string;
    }>;
    /**
     * Pass as `after` for the next batch; null on the last.
     */
    next_cursor?: string | null;
    /**
     * Pass as `before` for the previous batch; null on the first.
     */
    previous_cursor?: string | null;
};

